                semio_framework_dsl::LanguageSpec {
                    id: "din4108.document",
                    extension: Some("din4108"),
                    role: semio_framework_dsl::LanguageRole::Document,
                    grammar: Some(crate::standards::v1::subsets::any::io::text::snapshot::COMPONENT_GRAMMAR_SEMIO),
